import { MeshBasicNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, smoothstep } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const {
    Group,
    Mesh,
    PlaneGeometry,
    BoxGeometry,
    RingGeometry,
    CircleGeometry,
    DirectionalLight,
    PointLight,
    Color,
  } = THREE;

  const root = new Group();
  const stage = new Group();
  const subject = new Group();
  const resources = [];
  const primitiveResults = [];
  const timelines = [];
  let disposed = false;

  root.add(stage);
  root.add(subject);

  const ink = '#16161d';
  const paper = '#e8ecf2';
  const accent = '#ff2a38';
  const surface = '#0b0b10';

  const backdropGeometry = new PlaneGeometry(7, 6);
  const backdropMaterial = new MeshBasicNodeMaterial();
  const gradientY = smoothstep(0.0, 1.0, uv().y);
  backdropMaterial.colorNode = mix(
    vec3(0.043, 0.043, 0.063),
    mix(vec3(0.086, 0.086, 0.114), vec3(0.055, 0.055, 0.071), gradientY),
    gradientY
  );

  const backdrop = new Mesh(backdropGeometry, backdropMaterial);
  backdrop.position.set(0, -0.15, -2.5);
  stage.add(backdrop);
  resources.push(backdropGeometry, backdropMaterial);

  const cardGeometry = new BoxGeometry(3.05, 2.05, 0.18);
  const cardMaterial = new MeshStandardNodeMaterial({
    color: new Color(surface),
    roughness: 0.68,
    metalness: 0.42,
  });
  const card = new Mesh(cardGeometry, cardMaterial);
  card.position.set(0, 0, -1.15);
  stage.add(card);
  resources.push(cardGeometry, cardMaterial);

  const cardInsetGeometry = new BoxGeometry(2.82, 1.82, 0.035);
  const cardInsetMaterial = new MeshStandardNodeMaterial({
    color: new Color(ink),
    roughness: 0.76,
    metalness: 0.28,
  });
  const cardInset = new Mesh(cardInsetGeometry, cardInsetMaterial);
  cardInset.position.set(0, 0.09, -1.035);
  stage.add(cardInset);
  resources.push(cardInsetGeometry, cardInsetMaterial);

  const captionGeometry = new BoxGeometry(2.82, 0.34, 0.045);
  const captionMaterial = new MeshStandardNodeMaterial({
    color: new Color(ink),
    roughness: 0.72,
    metalness: 0.35,
  });
  const captionStrip = new Mesh(captionGeometry, captionMaterial);
  captionStrip.position.set(0, -0.72, -0.98);
  stage.add(captionStrip);
  resources.push(captionGeometry, captionMaterial);

  const accentRailGeometry = new BoxGeometry(0.055, 1.82, 0.06);
  const accentRailMaterial = new MeshStandardNodeMaterial({
    color: new Color(accent),
    emissive: new Color(accent),
    emissiveIntensity: 1.15,
    roughness: 0.52,
    metalness: 0.34,
  });
  const accentRail = new Mesh(accentRailGeometry, accentRailMaterial);
  accentRail.position.set(-1.41, 0.09, -0.91);
  stage.add(accentRail);
  resources.push(accentRailGeometry, accentRailMaterial);

  const rimGeometry = new RingGeometry(1.18, 1.205, 64);
  const rimMaterial = new MeshStandardNodeMaterial({
    color: new Color(accent),
    emissive: new Color(accent),
    emissiveIntensity: 1.25,
    roughness: 0.54,
    metalness: 0.38,
  });
  const rim = new Mesh(rimGeometry, rimMaterial);
  rim.position.set(0, 0.1, -0.82);
  rim.rotation.x = 0;
  stage.add(rim);
  resources.push(rimGeometry, rimMaterial);

  const contactGeometry = new CircleGeometry(1.62, 64);
  const contactMaterial = new MeshBasicNodeMaterial({
    color: new Color('#050509'),
    transparent: true,
    opacity: 0.48,
    depthWrite: false,
  });
  const contact = new Mesh(contactGeometry, contactMaterial);
  contact.scale.set(1.35, 0.38, 1);
  contact.position.set(0, -0.94, -0.75);
  contact.rotation.x = -Math.PI / 2;
  stage.add(contact);
  resources.push(contactGeometry, contactMaterial);

  const key = new DirectionalLight(paper, 1.1);
  key.position.set(3.2, 4.1, 5.5);
  root.add(key);

  const rimLight = new DirectionalLight(accent, 0.72);
  rimLight.position.set(-3.5, 1.8, 2.5);
  root.add(rimLight);

  const fill = new PointLight(paper, 0.42, 7, 2);
  fill.position.set(0, -0.4, 2.8);
  root.add(fill);

  const loadedMeshes = [];

  if (config.meshUrl && ctx.glbLoader?.loadGLB) {
    ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
      if (disposed || !gltf?.scene) return;

      const model = gltf.scene;
      model.position.set(0, 0.06, -0.28);
      model.scale.setScalar(1.08);
      subject.add(model);
      loadedMeshes.push(model);

      model.traverse((child) => {
        if (!child.isMesh) return;
        child.castShadow = true;
        child.receiveShadow = true;

        const materials = Array.isArray(child.material)
          ? child.material
          : [child.material];

        for (const material of materials) {
          if (!material) continue;
          if ('roughness' in material && material.roughness < 0.5) {
            material.roughness = 0.56;
          }
          if ('metalness' in material && material.metalness > 0.55) {
            material.metalness = 0.55;
          }
          if ('clearcoat' in material && material.clearcoat > 0.25) {
            material.clearcoat = 0.25;
          }
        }
      });

      const settle = gsap.timeline();
      settle.fromTo(
        subject.scale,
        { x: 0.94, y: 0.94, z: 0.94 },
        {
          x: 1.04,
          y: 1.04,
          z: 1.04,
          duration: 0.48,
          ease: 'power3.out',
        }
      ).to(subject.scale, {
        x: 1,
        y: 1,
        z: 1,
        duration: 0.9,
        ease: 'power4.out',
      }, '-=0.02');
      timelines.push(settle);
    }).catch(() => {});
  }

  const entrance = gsap.timeline();
  entrance.fromTo(
    stage.position,
    { y: -0.4 },
    { y: 0, duration: 0.7, ease: 'power3.out' }
  );
  timelines.push(entrance);

  const primitives = config.cinematicPrimitives ?? [];
  for (const primitive of primitives) {
    const apply = ctx.primitives?.[primitive.name];
    if (typeof apply === 'function') {
      const result = apply(root, primitive.params);
      if (result) {
        primitiveResults.push(result);
        if (result.timeline) timelines.push(result.timeline);
      }
    }
  }

  root.userData.handlers = {
    hover: (payload) => {
      const active = typeof payload === 'boolean'
        ? payload
        : payload?.active ?? payload?.over ?? true;

      if (active) {
        gsap.to(stage.position, {
          y: 0.15,
          duration: 0.3,
          ease: 'power2.out',
          overwrite: true,
        });
        gsap.to(stage.rotation, {
          z: 0.018,
          duration: 0.3,
          ease: 'power2.out',
          overwrite: true,
        });
      } else {
        gsap.to(stage.position, {
          y: 0,
          duration: 0.3,
          ease: 'power2.out',
          overwrite: true,
        });
        gsap.to(stage.rotation, {
          z: 0,
          duration: 0.3,
          ease: 'power2.out',
          overwrite: true,
        });
      }
    },
    click: () => {
      ctx.emit?.('hub-features.select', {
        node: config.id ?? config.name ?? 'hub-features-card-0',
      });
    },
  };

  root.userData.cleanup = () => {
    if (disposed) return;
    disposed = true;

    for (const timeline of timelines) {
      timeline?.kill?.();
    }

    for (const result of primitiveResults) {
      result?.cleanup?.();
    }

    for (const model of loadedMeshes) {
      model.traverse((child) => {
        if (!child.isMesh) return;

        if (child.geometry) child.geometry.dispose();

        const materials = Array.isArray(child.material)
          ? child.material
          : [child.material];

        for (const material of materials) {
          material?.dispose?.();
        }
      });
    }

    for (const resource of resources) {
      resource?.dispose?.();
    }

    root.clear();
  };

  return root;
}
